mapper.sql:
b.store_id = 1 and b.del_flag = '0' and b.publish_status = 1 and b.status <> 4

    and (b.title like concat('%', #{keyword}, '%')
      or b.author like concat('%', #{keyword}, '%')
      or b.isbn like concat('%', #{keyword}, '%')
      or b.publisher_name like concat('%', #{keyword}, '%'))

and b.category_id = #{categoryId}
and b.book_type = #{bookType}
and b.price >= #{minPrice}
and b.price <= #{maxPrice}
and exists (select 1 from biz_stock s
    where s.book_id = b.book_id and s.qty_available > 0)

mapper.select:
select b.book_id as bookId, b.isbn, b.title, b.author, b.publisher_name as publisherName, b.cover_url as coverUrl, b.price, b.member_price as memberPrice, b.book_type as bookType, b.sale_count as saleCount, b.status, coalesce((select sum(s.qty_available) from biz_stock s where s.book_id = b.book_id), 0) as qtyAvailable, (select l.location_code from biz_stock s2 join biz_location l on l.location_id = s2.location_id where s2.book_id = b.book_id and s2.qty_available > 0 order by s2.qty_available desc limit 1) as locationCode, (select c.category_name from biz_category c where c.category_id = b.category_id) as categoryName from biz_book b where
order by b.price asc, b.book_id desc order by b.price desc, b.book_id desc order by b.create_time desc, b.book_id desc order by b.sale_count desc, b.book_id desc
limit #{offset}, #{limit}

mapper.sql:
ub.store_id = 1 and ub.stock_status = 1
and (ub.title like concat('%', #{keyword}, '%') or ub.isbn like concat('%', #{keyword}, '%') or ub.author like concat('%', #{keyword}, '%'))
and exists (select 1 from biz_book b where b.book_id = ub.book_id and b.category_id = #{categoryId}) and ub.used_price >= #{minPrice} and ub.used_price <= #{maxPrice}

mapper.select:
select ub.used_book_id as usedBookId, ub.book_id as bookId, ub.isbn, ub.title, ub.author, ub.publisher_name as publisherName, ub.cover_url as coverUrl, ub.condition_grade_name as conditionGradeName, ub.origin_price as originPrice, ub.used_price as usedPrice, ub.stock_status as stockStatus, ub.shelf_time as shelfTime, ub.bar_code as barCode from biz_used_book ub where
order by ub.used_price asc order by ub.used_price desc order by ub.shelf_time desc, ub.used_book_id desc
limit #{offset}, #{limit}

select b.book_id as bookId, b.isbn, b.title, b.author, b.cover_url as coverUrl,
       b.price, b.sale_count as saleCount
from biz_book b
where b.store_id = 1 and b.del_flag = '0' and b.publish_status = 1
  and b.status <> 4 and b.category_id = #{categoryId}
  and b.book_id <> #{excludeBookId}
order by b.sale_count desc
limit #{limit}

select ub.used_book_id as usedBookId, ub.isbn, ub.title, ub.author, ub.cover_url as coverUrl, ub.condition_grade_name as conditionGradeName, (select g.grade_desc from biz_condition_grade g where g.grade_id = ub.condition_grade_id) as conditionDesc, ub.origin_price as originPrice, ub.used_price as usedPrice, ub.stock_status as stockStatus, ub.bar_code as barCode from biz_used_book ub where ub.store_id = 1 and ub.stock_status = 1
and (ub.title like concat('%', #{keyword}, '%') or ub.isbn like concat('%', #{keyword}, '%') or ub.author like concat('%', #{keyword}, '%'))
and exists (select 1 from biz_book b where b.book_id = ub.book_id and b.category_id = #{categoryId}) and ub.condition_grade_id = #{conditionGradeId} and ub.used_price >= #{minPrice} and ub.used_price <= #{maxPrice}
order by ub.used_price asc order by ub.used_price desc order by ub.shelf_time desc, ub.used_book_id desc
limit #{offset}, #{limit}

select count(*) from biz_used_book ub where ub.store_id = 1 and ub.stock_status = 1

    and (ub.title like concat('%', #{keyword}, '%') or ub.isbn like concat('%', #{keyword}, '%')
      or ub.author like concat('%', #{keyword}, '%'))

and exists (select 1 from biz_book b
    where b.book_id = ub.book_id and b.category_id = #{categoryId})
and ub.condition_grade_id = #{conditionGradeId}
and ub.used_price >= #{minPrice}
and ub.used_price <= #{maxPrice}
